UPDATE domain_providers SET register_url = COALESCE(NULLIF(register_url, ''), 'https://www.dynadot.com/account/create'), description = COALESCE(NULLIF(description, ''), '域名投资者青睐的注册商, 支持批量操作 + 域名交易市场'), commission_model = COALESCE(NULLIF(commission_model, ''), '按年付费, 价格中等 (如 .com $11.99/年), 转入优惠多') WHERE code = 'dynadot';
